import {createRange} from './scene3d.js';
import {ArcheryAudio} from './audio.js';
import {TARGET_RADIUS,BULLSEYE_RADIUS,X_RING_RADIUS,ringRadius} from './target-config.js';
const archeryAudio=new ArcheryAudio();
const $=id=>document.getElementById(id),canvas=$('game'),range3d=createRange(canvas);
export class EventBus extends EventTarget{emit(type,detail){this.dispatchEvent(new CustomEvent(type,{detail}));}on(type,fn){this.addEventListener(type,e=>fn(e.detail));}}
const bus=new EventBus();
// TODO: [Extension Hook] Load bow, arrow, stabilizer and weather presets from JSON.
export const equipment={drawForce:5.1,arrowMass:.025,efficiency:.35,Cd:1.1,area:.00004,rho:1.225,shaftRadius:.004,windResponse:.65};
export class PhysicsEngine{
 step(a,dt,wind){let v=a.v,speed=Math.hypot(v.x-wind,v.y,v.z),k=.5*equipment.rho*equipment.Cd*equipment.area/equipment.arrowMass;v.x+=(-k*speed*(v.x-wind)+wind*equipment.windResponse)*dt;v.y+=(-9.81-k*speed*v.y)*dt;v.z-=k*speed*v.z*dt;a.p.x+=v.x*dt;a.p.y+=v.y*dt;a.p.z+=v.z*dt;}
 trace(aim,power,wind,distance){let a=this.launch(aim,power),points=[{...a.p}];for(let i=0;i<2400;i++){let old={...a.p};this.step(a,1/240,wind);if(i%12===0)points.push({...a.p});if(a.p.z>=distance){let t=(distance-old.z)/(a.p.z-old.z);return{points,hit:{x:old.x+(a.p.x-old.x)*t,y:old.y+(a.p.y-old.y)*t,z:distance}};}if(a.p.y<-8)break;}return{points,hit:null};}
 minimumDraw(distance){
 this.drawThresholds??=new Map();if(this.drawThresholds.has(distance))return this.drawThresholds.get(distance);
 let low=0,high=1;for(let i=0;i<14;i++){let power=(low+high)/2,aim=this.solveAim({x:0,y:1.5},power,0,distance),hit=this.trace(aim,power,0,distance).hit;if(hit&&Math.abs(hit.y-1.5)<.01)high=power;else low=power;}
 const reliableDraw=({10:.2,20:.35,30:.5,50:.75,70:.9,90:1})[distance]??1;const minimum=Math.max(reliableDraw,Math.min(1,Math.ceil(high*100)/100+.02));this.drawThresholds.set(distance,minimum);return minimum;
 }
 // Solve drop assistance in still air. Gameplay deliberately passes wind=0 here so players must aim into the actual crosswind.
 solveAim(point,power,wind,distance){
 const speed=equipment.drawForce/equipment.arrowMass*equipment.efficiency*(.25+.75*power),height=point.y-1.5;
 const discriminant=speed**4-9.81*(9.81*distance**2+2*height*speed**2);
 let angle=discriminant>=0?Math.atan((speed**2-Math.sqrt(discriminant))/(9.81*distance)):.65;
 let aim={x:point.x/distance-.5*wind*equipment.windResponse*distance/speed**2,y:Math.tan(angle)};
 for(let i=0;i<7;i++){let hit=this.trace(aim,power,wind,distance).hit;if(!hit)break;let dx=point.x-hit.x,dy=point.y-hit.y;if(Math.hypot(dx,dy)<.0005)break;aim.x+=dx/distance;aim.y+=dy/distance;}
 return aim;
 }
 launch(aim,power){let speed=equipment.drawForce/equipment.arrowMass*equipment.efficiency*(.25+.75*power),norm=Math.hypot(aim.x,aim.y,1);return{p:{x:0,y:1.5,z:0},v:{x:speed*aim.x/norm,y:speed*aim.y/norm,z:speed/norm}};}
}
// Wind stays steady for one shot so the assist and flight use identical conditions.
export class WindController{
 next(previous=0){const speeds=Array.from({length:51},(_,i)=>(i+5)/10).filter(speed=>speed!==Math.round(Math.abs(previous)*10)/10);const direction=previous===0?(Math.random()<.5?-1:1):-Math.sign(previous);return speeds[Math.floor(Math.random()*speeds.length)]*direction;}
}
export class TargetManager{constructor(){this.radius=TARGET_RADIUS;this.centerY=1.5;this.arrows=[];}reset(){this.arrows=[];}
 // TODO: [Extension Hook] Animate center position for rail, pendulum, or pop-up targets.
}
export class ScoringSystem{score(hit,target){if(!hit)return{points:0,label:'OUT OF RANGE',bonus:0};let r=Math.hypot(hit.x,hit.y-target.centerY),cut=Math.max(0,r-equipment.shaftRadius),points=cut<=target.radius?Math.min(10,11-Math.ceil(cut/(target.radius/10))):0;if(points===10&&cut>BULLSEYE_RADIUS)points=9;let x=r<X_RING_RADIUS,robin=points>0&&target.arrows.some(a=>Math.hypot(a.x-hit.x,a.y-hit.y)<.012);return{points,label:robin?'ROBIN HOOD':x?'PERFECT X':points===10?'BULLSEYE':points>=9?'IN THE GOLD':points?'ON THE BOARD':'JUST WIDE',bonus:points===10?5+(x?5:0):0};}}
export class BowController{constructor(){this.aim={x:0,y:.035};this.pointer={x:0,y:0};this.drawing=false;this.power=0;this.held=0;}update(dt){if(this.drawing){this.held+=dt;this.power=Math.min(1,this.held/1.15);}}getAim(time){let sway=.0003+Math.max(0,this.held-3)*.00055;return{x:this.aim.x+Math.sin(time*2.3)*sway,y:this.aim.y+Math.cos(time*1.8)*sway};}}
export class CinematicCameraDirector{constructor(){this.active=false;this.zoom=1;this.drawZoom=1;this.hold=0;}start(prediction){this.bullseye=!!prediction&&Math.hypot(prediction.x,prediction.y-1.5)<=BULLSEYE_RADIUS+equipment.shaftRadius;this.active=true;this.hold=0;}update(dt,arrow,distance,drawing=false,drawPower=0){
// Holding the trigger smoothly narrows the aiming view; release or cancellation restores it.
let aimZoom=drawing?1.45+.35*drawPower:1;
this.drawZoom+=(aimZoom-this.drawZoom)*(1-Math.exp(-dt*6));
let desired=this.active?3.6:1;this.zoom+=(desired-this.zoom)*Math.min(1,dt*5);if(this.active&&!arrow){this.hold+=dt;if(this.hold>1.6)this.active=false;}return this.active&&arrow?(arrow.p.z>distance*.65?.25:.6):1;}}
export class UIManager{update(){ $('score').textContent=String(game.score).padStart(2,'0');$('best').textContent=String(game.best).padStart(2,'0');$('quiver').textContent=Array(game.remaining).fill('↟').join(' ' )||'—';$('remaining').textContent=`${game.remaining} arrows remaining`;$('combo').textContent=game.combo?`${game.combo}×`:'—';$('powerLabel').textContent=Math.round(bow.power*100)+'%';const minimum=physics.minimumDraw(game.distance);$('drawTitle').textContent=`DRAW POWER · MIN ${Math.ceil(minimum*100)}%`;$('powerBar').parentElement.style.setProperty('--min-draw',minimum*100+'%');$('powerBar').style.width=bow.power*100+'%';$('distanceLabel').textContent=game.distance;document.querySelectorAll('[data-distance]').forEach(button=>button.setAttribute('aria-pressed',String(Number(button.dataset.distance)===game.distance)));$('windLabel').innerHTML=`${game.wind>=0?'→':'←'} ${Math.abs(game.wind).toFixed(1)} m/s <small>${game.wind>=0?'PUSHES RIGHT · AIM LEFT':'PUSHES LEFT · AIM RIGHT'}</small>`;}
 callout(title,sub){$('callout').innerHTML=`<small>${sub}</small><strong>${title}</strong>`;$('callout').style.opacity=1;game.calloutTime=3;}
 summary(){let hits=game.shots.filter(s=>s.points>0).length;$('summaryTitle').textContent=`${game.score} / 60. ${game.score>=45?'Beautifully placed.':'Every shot is progress.'}`;$('summaryText').textContent=`${Math.round(hits/6*100)}% target accuracy · ${(game.score/6).toFixed(1)} average · ${game.bonus} bonus points`;$('summary').hidden=false;let g=$('group').getContext('2d');g.clearRect(0,0,180,180);drawTarget(g,90,90,78);for(let s of game.shots){if(s.hit){g.fillStyle='#526d37';g.beginPath();g.arc(90+s.hit.x/.65*78,90-(s.hit.y-1.5)/.65*78,3,0,7);g.fill();g.strokeStyle='white';g.stroke();}}}}
const windController=new WindController();
const physics=new PhysicsEngine(),target=new TargetManager(),scoring=new ScoringSystem(),bow=new BowController(),camera=new CinematicCameraDirector(),ui=new UIManager();
let best=0;try{best=Number(localStorage.getItem('flight-best'))||0;}catch{}const game={distance:30,wind:windController.next(),score:0,best,remaining:6,combo:0,bonus:0,shots:[],arrow:null,pendingWind:null,lastDrift:null,particles:[],calloutTime:5,round:1};let W=1000,H=440,time=0,last=0,sound=true,summaryTimer;
function reset(){archeryAudio.stopFlight();clearTimeout(summaryTimer);$('windResult').hidden=true;game.round++;Object.assign(game,{score:0,remaining:6,combo:0,bonus:0,shots:[],arrow:null,pendingWind:null,lastDrift:null,particles:[],wind:windController.next(game.wind)});target.reset();camera.active=false;camera.hold=0;camera.drawZoom=1;bow.pointer={x:0,y:0};bow.drawing=false;bow.power=0;$('summary').hidden=true;$('roundLabel').innerHTML=`ROUND ${String(game.round).padStart(2,'0')} <b> • </b> 6 ARROWS`;ui.callout('Make your next mark.','A FRESH START');ui.update();}
function start(){if(game.arrow||camera.active||!game.remaining||!$('summary').hidden)return;bow.drawing=true;bow.held=0;archeryAudio.unlock();archeryAudio.draw();}
function release(){if(!bow.drawing)return;updateAim();bow.drawing=false;if(bow.power<physics.minimumDraw(game.distance)){bow.power=0;ui.callout(`Draw further for ${game.distance} meters.`,`MINIMUM ${Math.ceil(physics.minimumDraw(game.distance)*100)}% POWER · ARROW KEPT`);return;}let aim=bow.getAim(time),trace=physics.trace(aim,bow.power,game.wind,game.distance);game.arrow=physics.launch(aim,bow.power);game.arrow.wind=game.wind;game.arrow.calmHit=physics.trace(aim,bow.power,0,game.distance).hit;game.arrow.trail=[{...game.arrow.p}];game.remaining--;camera.start(trace.hit);archeryAudio.release(bow.power);bus.emit('shot',{power:bow.power});bow.power=0;ui.update();}
function impact(hit){let s=scoring.score(hit,target);game.score+=s.points;game.bonus+=s.bonus;game.combo=s.points>=9?game.combo+1:0;const drift=hit&&game.arrow.calmHit?hit.x-game.arrow.calmHit.x:null;game.lastDrift=drift;game.shots.push({...s,hit,wind:game.arrow.wind,drift});$('windResult').hidden=drift===null;if(drift!==null)$('windResult').textContent=`LAST SHOT · WIND DRIFT ${drift>=0?'→':'←'} ${Math.abs(drift)<1?(Math.abs(drift)*100).toFixed(1)+' cm':Math.abs(drift).toFixed(2)+' m'} · ${game.distance}m`;if(s.points){target.arrows.push({...hit,age:0,v:{...game.arrow.v}});for(let i=0;i<20;i++)game.particles.push({x:hit.x,y:hit.y,z:hit.z,vx:(Math.random()-.5)*1.7,vy:Math.random()*1.8,vz:-Math.random(),life:1});}game.arrow=null;game.pendingWind=windController.next(game.wind);game.best=Math.max(game.best,game.score);try{localStorage.setItem('flight-best',game.best);}catch{}ui.callout(s.label,s.points?`+${s.points} POINTS${s.bonus?' · +'+s.bonus+' BONUS':''}`:'ADJUST YOUR AIM & TRY AGAIN');archeryAudio.impact(s.points);bus.emit('impact',s);ui.update();if(!game.remaining)summaryTimer=setTimeout(()=>ui.summary(),2200);}
function project(p){let camz=camera.zoom>1?game.distance*(1-1/camera.zoom):0;let depth=Math.max(.4,p.z-camz+6),scale=H*2.8*camera.drawZoom/depth;return{x:W/2+p.x*scale,y:H*.49-(p.y-1.5)*scale,s:scale};}
function drawTarget(c,x,y,r){let colors=['#ecebe0','#ecebe0','#303a35','#303a35','#59869a','#59869a','#bc5c47','#bc5c47','#e8bd55','#e8bd55'];for(let i=0;i<10;i++){c.beginPath();c.arc(x,y,r*ringRadius(i)/TARGET_RADIUS,0,Math.PI*2);c.fillStyle=colors[i];c.fill();c.strokeStyle=i>7?'#b38b3c':'#34423655';c.lineWidth=.7;c.stroke();}c.beginPath();c.arc(x,y,r*X_RING_RADIUS/TARGET_RADIUS,0,7);c.strokeStyle='#977b32';c.stroke();}
function frame(ms){let dt=Math.min(.04,(ms-last)/1000||.016);last=ms;time+=dt;bow.update(dt);let scale=camera.update(dt,game.arrow,game.distance,bow.drawing,bow.power);if(!game.arrow&&!camera.active){if(game.pendingWind!==null){game.wind=game.pendingWind;game.pendingWind=null;}updateAim();}canvas.parentElement.classList.toggle('cinematic',camera.active);$('cine').hidden=!camera.active;$('cine').innerHTML=game.arrow?'◎ ARROW CHASE <span>SLOW MOTION</span>':`◎ ${camera.bullseye?'BULLSEYE':'IMPACT'} CAM`;$('status').textContent=game.arrow?'ARROW IN FLIGHT':bow.drawing?(bow.held>3?'STEADY YOUR BREATH':'DRAWING · RELEASE WHEN READY'):'HOLD TO DRAW · RELEASE TO SHOOT';if(game.arrow){let remaining=dt*scale;while(remaining>0&&game.arrow){let step=Math.min(1/240,remaining),old={...game.arrow.p};physics.step(game.arrow,step,game.arrow.wind);game.arrow.trail.push({...game.arrow.p});if(game.arrow.trail.length>160)game.arrow.trail.shift();let p=game.arrow.p;if(p.z>=game.distance){let t=(game.distance-old.z)/(p.z-old.z);impact({x:old.x+(p.x-old.x)*t,y:old.y+(p.y-old.y)*t,z:game.distance});}else if(p.y<-5)impact(null);remaining-=step;}}for(let p of game.particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;p.vy-=3*dt;}game.particles=game.particles.filter(p=>p.life>0);game.calloutTime-=dt;if(game.calloutTime<0)$('callout').style.opacity=0;if(game.arrow)archeryAudio.updateFlight(game.arrow.p.z/game.distance,Math.hypot(game.arrow.v.x,game.arrow.v.y,game.arrow.v.z),game.arrow.wind);ui.update();range3d.render({game,controller:bow,director:camera,physics,assist:$('preview').checked,dt,time,width:W,height:H});requestAnimationFrame(frame);}
function updateAim(){
 const point=range3d.aimPoint(bow.pointer,game.distance,camera.drawZoom,W/H);
 const power=bow.drawing?bow.power:1;
 bow.aim=$('assist').checked?physics.solveAim(point,power,0,game.distance):{x:point.x/game.distance,y:(point.y-1.5)/game.distance};
}
function aim(e){if(game.arrow||camera.active)return;const rect=canvas.getBoundingClientRect();bow.pointer={x:(e.clientX-rect.left)/rect.width*2-1,y:1-(e.clientY-rect.top)/rect.height*2};updateAim();}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();aim(e);canvas.setPointerCapture(e.pointerId);start();});canvas.addEventListener('pointermove',aim);canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',()=>{bow.drawing=false;bow.power=0;});window.addEventListener('keydown',e=>{if(e.target.matches('button,select,input')||$('rules').open)return;if(e.code==='Space'){e.preventDefault();if(!e.repeat)start();}if(e.code==='KeyT')$('preview').checked=!$('preview').checked;if(e.code==='KeyR')reset();});window.addEventListener('keyup',e=>{if(e.code==='Space')release();});window.addEventListener('blur',()=>{bow.drawing=false;bow.power=0;});$('reset').onclick=reset;$('again').onclick=reset;$('distance').onclick=e=>{let button=e.target.closest('[data-distance]');if(!button)return;let distance=Number(button.dataset.distance);if(distance===game.distance)return;game.distance=distance;reset();ui.callout(`${distance} meters. Find your focus.`,'NEW DISTANCE · FRESH ROUND');};$('sound').onclick=()=>{sound=!sound;archeryAudio.setEnabled(sound);$('sound').textContent=sound?'SOUND ON ♫':'SOUND OFF ♫';$('sound').setAttribute('aria-pressed',String(sound));};$('help').onclick=()=>$('rules').showModal();$('close').onclick=()=>$('rules').close();new ResizeObserver(()=>{let r=canvas.getBoundingClientRect();W=r.width;H=r.height;}).observe(canvas);ui.update();requestAnimationFrame(frame);
